-- AllianceOS audit follow-up — pagination, result archiving, legacy normalization.
-- No rows are deleted.

alter table public.campaign_results add column if not exists arquivado_em timestamptz;
alter table public.campaign_results add column if not exists arquivado_por uuid references auth.users(id);
alter table public.campaign_results add column if not exists historico jsonb not null default '[]'::jsonb;

drop index if exists public.campaign_results_identity_uq;
create unique index if not exists campaign_results_active_identity_uq
  on public.campaign_results(campaign_id,coalesce(fonte_receita,''),coalesce(canal,''),data)
  where arquivado_em is null;
create index if not exists campaign_results_archive_idx on public.campaign_results(arquivado_em);
create index if not exists campaign_results_brand_date_idx on public.campaign_results(brand_id,data);

create table if not exists public.legacy_member_names(
  id uuid primary key default gen_random_uuid(),
  nome text not null unique,
  cargo text,
  observacoes text,
  origem text not null default 'interface' check (origem in ('interface','mcp')),
  criado_por uuid references auth.users(id) default auth.uid(),
  atualizado_por uuid references auth.users(id) default auth.uid(),
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  arquivado_em timestamptz,
  arquivado_por uuid references auth.users(id)
);
alter table public.legacy_member_names enable row level security;
drop policy if exists legacy_member_names_read on public.legacy_member_names;
create policy legacy_member_names_read on public.legacy_member_names for select to authenticated using (app.estou_ativo() and not app.eh_externo());
drop policy if exists legacy_member_names_insert on public.legacy_member_names;
create policy legacy_member_names_insert on public.legacy_member_names for insert to authenticated with check (app.estou_ativo() and not app.eh_externo());
drop policy if exists legacy_member_names_update on public.legacy_member_names;
create policy legacy_member_names_update on public.legacy_member_names for update to authenticated using (app.estou_ativo() and not app.eh_externo()) with check (app.estou_ativo() and not app.eh_externo());
grant select,insert,update on public.legacy_member_names to authenticated;
revoke all on public.legacy_member_names from anon;
revoke delete,truncate on public.legacy_member_names from authenticated,anon,public;

insert into public.legacy_member_names(nome,cargo,observacoes,origem)
values ('Ana Medeiros','Creators e influenciadoras','Incluída como nome legado após auditoria; nenhuma tarefa antiga com variação inequívoca do nome foi encontrada.','mcp')
on conflict (nome) do update set cargo=excluded.cargo,observacoes=excluded.observacoes,arquivado_em=null,atualizado_em=now();

-- Archive the two explicitly identified audit/test results; keep them queryable.
update public.campaign_results
set arquivado_em=coalesce(arquivado_em,now()),
    arquivado_por=coalesce(arquivado_por,criado_por),
    historico=jsonb_build_array(jsonb_build_object('at',now(),'by','Migração AllianceOS','authorId',criado_por,'origin','mcp','text','Resultado de auditoria arquivado sem exclusão.'))||coalesce(historico,'[]'::jsonb),
    atualizado_em=now()
where id in ('94158090-d61b-4622-8208-e8e9b91ab78c','6daf5561-6144-42a0-94db-5f06ffbdaa07');

-- Normalize migrated delivery statuses in the official collection.
update public.operacional_estado o
set valor=(
  select coalesce(jsonb_agg(
    case lower(coalesce(d->>'status',''))
      when 'sent' then jsonb_set(d,'{status}','"enviado"'::jsonb,true)
      when 'approved' then jsonb_set(d,'{status}','"aprovado"'::jsonb,true)
      when 'rejected' then jsonb_set(d,'{status}','"ajustes"'::jsonb,true)
      else d end
  ),'[]'::jsonb)
  from jsonb_array_elements(o.valor) d
), atualizado_em=now()
where o.chave='central.deliveries.workspace.v1' and o.dono is null;

-- Normalize statuses in embedded task delivery copies too.
update public.operacional_estado o
set valor=(
  select coalesce(jsonb_agg(
    case when jsonb_typeof(t->'deliveries')='array' then
      jsonb_set(t,'{deliveries}',coalesce((
        select jsonb_agg(
          case lower(coalesce(d->>'status',''))
            when 'sent' then jsonb_set(d,'{status}','"enviado"'::jsonb,true)
            when 'approved' then jsonb_set(d,'{status}','"aprovado"'::jsonb,true)
            when 'rejected' then jsonb_set(d,'{status}','"ajustes"'::jsonb,true)
            else d end
        ) from jsonb_array_elements(t->'deliveries') d
      ),'[]'::jsonb),true)
    else t end
  ),'[]'::jsonb)
  from jsonb_array_elements(o.valor) t
), atualizado_em=now()
where o.chave='central.tasks.vitor-gutierrez' and o.dono is null;

